SELECT (microbiologyevents.instability_score - lag(microbiologyevents.instability_score) OVER (PARTITION BY icustays.subject_id ORDER BY chartevents.charttime)) / NULLIF((q3 - q1), 0) AS percentile_rank, AVG(icustays.los) AS average_los, COUNT(*) filter (WHERE deathtime IS NOT NULL) AS mortality_rate FROM male_icu_patients JOIN quartiles ON TRUE JOIN mortality ON TRUE WHERE microbiologyevents.instability_score IS NOT NULL AND lag(microbiologyevents.instability_score) OVER (PARTITION BY icustays.subject_id ORDER BY chartevents.charttime) IS NOT NULL GROUP BY percentile_rank, average_los, mortality_rate;